#!/usr/bin/env node
/**
 * R327 C4 — per-module bundle size analyzer for Metro exports.
 * Reads a Metro source map (JSON), attributes generated bytes to sources,
 * and prints the top offenders + totals. Compares two maps when given both.
 *
 * Usage:
 *   node analyze-bundle.mjs <map-file> [--top N]
 *   node analyze-bundle.mjs <head-map> --vs <base-map> [--top N]
 */
import fs from "node:fs";

function loadMap(p) {
  const raw = JSON.parse(fs.readFileSync(p, "utf8"));
  // Metro may emit either a plain map or { version, mappings, sources } —
  // react-native/compose-source-maps style. Normalize.
  return raw;
}

/** VLQ decode a sourcemap's mappings into per-source generated lengths. */
function attribute(m) {
  const sources = m.sources ?? [];
  const perSource = new Array(sources.length).fill(0);
  const lines = (m.mappings ?? "").split(";");
  let srcIdx = 0;
  let prevGenCol = 0;
  let prevLine = 0;
  let prevCol = 0;
  const segsByLine = [];
  for (let li = 0; li < lines.length; li++) {
    const segs = lines[li].split(",");
    let genCol = 0;
    const parsed = [];
    for (const seg of segs) {
      if (!seg) continue;
      const fields = decodeVLQ(seg);
      genCol += fields[0];
      if (fields.length >= 4) {
        srcIdx += fields[1];
        prevLine += fields[2];
        prevCol += fields[3];
      }
      parsed.push({ genCol, srcIdx });
    }
    segsByLine.push(parsed);
  }
  // attribute: each segment owns [genCol, nextSegCol) on its line
  for (let li = 0; li < segsByLine.length; li++) {
    const segs = segsByLine[li];
    for (let si = 0; si < segs.length; si++) {
      const start = segs[si].genCol;
      const end = si + 1 < segs.length ? segs[si + 1].genCol : Infinity;
      const width = end === Infinity ? 0 : Math.max(0, end - start);
      if (segs[si].srcIdx >= 0 && segs[si].srcIdx < perSource.length) {
        perSource[segs[si].srcIdx] += width;
      }
    }
  }
  return { sources, perSource };
}

function decodeVLQ(str) {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  const out = [];
  let shift = 0;
  let value = 0;
  for (const c of str) {
    const d = chars.indexOf(c);
    if (d < 0) continue;
    const cont = d & 32;
    value += (d & 31) << shift;
    if (cont) {
      shift += 5;
    } else {
      const neg = value & 1;
      value >>= 1;
      out.push(neg ? -value : value);
      value = 0;
      shift = 0;
    }
  }
  return out;
}

function kb(n) {
  return (n / 1024).toFixed(1);
}

const args = process.argv.slice(2);
const topIdx = args.indexOf("--top");
const TOP = topIdx !== -1 ? parseInt(args[topIdx + 1] || "30", 10) : 30;
const vsIdx = args.indexOf("--vs");

const head = attribute(loadMap(args[0]));
const rows = head.sources
  .map((s, i) => ({ src: s, gen: head.perSource[i] }))
  .filter((r) => r.gen > 0)
  .sort((a, b) => b.gen - a.gen);

console.log(`== ${args[0]} ==`);
console.log(`sources with mapped bytes: ${rows.length}`);

if (vsIdx !== -1) {
  const base = attribute(loadMap(args[vsIdx + 1]));
  const baseMap = new Map();
  base.sources.forEach((s, i) => baseMap.set(s, base.perSource[i]));
  const deltas = rows.map((r) => ({
    src: r.src,
    head: r.gen,
    base: baseMap.get(r.src) ?? 0,
    delta: r.gen - (baseMap.get(r.src) ?? 0),
  }));
  // also sources only in base (removed)
  for (const [s, g] of baseMap) {
    if (g > 0 && !head.sources.includes(s)) deltas.push({ src: s, head: 0, base: g, delta: -g });
  }
  deltas.sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta));
  console.log(`\ntop ${TOP} by |delta| (generated bytes, approx):`);
  for (const d of deltas.slice(0, TOP)) {
    console.log(
      `${d.delta >= 0 ? "+" : "-"}${kb(Math.abs(d.delta))}kB  head=${kb(d.head)}kB base=${kb(d.base)}kB  ${d.src}`
    );
  }
  const totalHead = head.perSource.reduce((a, b) => a + b, 0);
  const totalBase = base.perSource.reduce((a, b) => a + b, 0);
  console.log(
    `\nmapped-total: head=${kb(totalHead)}kB base=${kb(totalBase)}kB delta=${kb(totalHead - totalBase)}kB`
  );
} else {
  console.log(`\ntop ${TOP} sources by generated bytes (approx):`);
  for (const r of rows.slice(0, TOP)) {
    console.log(`${kb(r.gen)}kB  ${r.src}`);
  }
  const total = rows.reduce((a, r) => a + r.gen, 0);
  console.log(`mapped-total: ${kb(total)}kB`);
}
